Translate("frFR", "blackfathom-deeps", {
	title = "Profondeurs de Brassenoire",
	aliases = { "Brassenoire" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Profondeurs de Brassenoire sont un temple englouti sous la côte d'{link:ashenvale}Orneval{/link}, sur la {link:the-zoram-strand}grève de Zoram{/link}. Un puits bordé de vieux escaliers descend du rivage jusque dans l'eau sombre, et il faut nager pour entrer. Au-delà s'étendent des cavernes inondées, des sanctuaires brisés et des salles englouties de pâle pierre elfique. Ce fut jadis un lieu saint de la déesse de la lune, Elune. Il appartient désormais au {link:twilight-s-hammer}Marteau du crépuscule{/link}, aux {link:naga}nagas{/link} et aux {link:satyrs}satyres{/link} qui servent à ses côtés, et à la chose qu'ils vénèrent dans le bassin le plus profond : l'hydre {link:aku-mai}Aku'mai{/link}.]=],
		},
		{
			title = "Origines",
			text = [=[À l'âge qui précéda la {link:great-sundering}Grande Fracture{/link}, les {link:night-elves}elfes de la nuit{/link} élevèrent un grand temple à Elune sur la rive occidentale de l'ancien {link:kalimdor}Kalimdor{/link}. Il est écrit que la {link:queen-azshara}reine Azshara{/link} elle-même en surveilla la construction. En son cœur se trouvait un puits de lune. Quand la Fracture déchira le monde, le temple se brisa et sombra sous les flots, et il resta perdu et silencieux pendant des âges. Même alors, il ne renfermait pas que des choses saintes. Un elfe nommé Lorgalis, adorateur des {red:old-gods}Dieux très anciens{/red}, laissa entre ses murs un manuscrit à leur louange, et celui-ci ne fut jamais détruit.

Plus tard, une corruption des Dieux très anciens suinta du fond de la terre et souilla le puits de lune sacré. {link:aku-mai}Aku'mai{/link}, une servante de ces puissances anciennes, surgit des eaux et fit des ruines son antre.]=],
		},
		{
			title = "De nos jours",
			text = [=[Le {link:twilight-s-hammer}Marteau du crépuscule{/link} est venu dans les Profondeurs pour vénérer l'hydre. Ses cultistes sont de nombreux peuples, humains et orcs, trolls, taurens et même {link:forsaken}Réprouvés{/link}, tous liés par leur foi dans le retour des Dieux très anciens. Menés par le seigneur du crépuscule {link:twilight-lord-kelris}Kelris{/link}, ils offrent des innocents à {link:aku-mai}Aku'mai{/link} en échange de pouvoir. Les nagas de la tribu Brassenoire les ont rejoints, et des satyres Fallenroot hantent les tunnels. Les nagas récoltent des saphirs sur les parois des grottes, car les esprits de l'eau s'attachent à ces pierres.

Le monde d'en haut s'en est aperçu. L'{link:argent-dawn}Aube d'argent{/link}, à {link:darnassus}Darnassus{/link}, envoya un éclaireur surveiller le temple, et il ne revint pas. Le {link:earthen-ring}Cercle terrestre{/link} envoya le troll {link:je-neu-sancrea}Je'neu Sancrea{/link} sur la {link:the-zoram-strand}grève de Zoram{/link} pour découvrir ce que le culte fait aux éléments. {link:gershala-nightwhisper}Gershala Nightwhisper{/link}, d'{link:auberdine}Auberdine{/link}, veut les cerveaux des nagas et des satyres corrompus pour ses études, et {red:gerrig-bonegrip}Gerrig Bonegrip{/red}, d'{link:ironforge}Ironforge{/link}, convoite le manuscrit de Lorgalis.]=],
		},
		{
			title = "Dans les Profondeurs",
			text = [=[• {b}L'entrée engloutie.{/b} Des escaliers et des passages inondés descendent depuis le rivage. Des amas de saphirs scintillent sur les parois, et des prêtresses nagas les récoltent.
• {b}Le bassin d'Ask'ar.{/b} Une grande grotte inondée avec une île en son centre, où rôde la tortue rendue folle {link:ghamoo-ra}Ghamoo-ra{/link}. L'éclaireur blessé {link:argent-guard-thaelrid}Thaelrid{/link} se cache non loin. Dans une anse latérale, la sorcière des mers dame {link:lady-sarevess}Sarevess{/link} tient sa propre cour.
• {b}Le sanctuaire de {link:gelihast}Gelihast{/link}.{/b} Les murlocs Blindlight se rassemblent ici autour de leur chef et de son autel.
• {b}Les ruines du Sanctuaire lunaire.{/b} Les salles brisées de l'ancien temple, à moitié sous l'eau, où les cultistes ont leurs camps. Une pierre des abysses repose dans l'eau, et quelque chose d'élémentaire la garde.
• {b}Le bassin oublié.{/b} Sous les ruines, une grotte engloutie où un ancien batteur n'a jamais été pris.
• {b}Le sanctum du Sanctuaire lunaire.{/b} Ici, le seigneur du crépuscule {link:twilight-lord-kelris}Kelris{/link} est assis en transe devant l'autel des Dieux très anciens.
• {b}L'antre d'{link:aku-mai}Aku'mai{/link}.{/b} Au-delà des portes scellées du sanctum s'étend le bassin le plus profond, où l'hydre attend.]=],
		},
	},
})

Translate("frFR", "lorgalis-manuscript", {
	title = "Manuscrit de Lorgalis",
	found = [=[Un coffre en fer piqué dans les profondeurs des Profondeurs de Brassenoire]=],
	sections = {
		{
			title = "Notes",
			text = [=[Un bref écrit à la louange des {red:old-gods}Dieux très anciens{/red}, laissé dans le temple englouti par un elfe nommé Lorgalis. L'auteur appelle les Dieux très anciens les premiers maîtres du monde, aujourd'hui enchaînés et endormis, et enseigne que seuls ceux qui s'agenouillent devant leurs serviteurs trouveront grâce. Sa dernière page nomme {link:aku-mai}Aku'mai{/link} comme l'une de ces servantes et l'appelle la Princesse des profondeurs, amenée au temple par des mortels plus anciens et vénérée là comme un signe de divinité. {red:gerrig-bonegrip}Gerrig Bonegrip{/red}, d'{link:ironforge}Ironforge{/link}, veut que le manuscrit soit copié et partagé entre ses frères et sœurs.]=],
		},
	},
})

Translate("frFR", "aku-mai", {
	title = "Aku'mai",
	subtitle = "Princesse des profondeurs",
	found = [=[L'antre d'Aku'mai, le bassin le plus profond des Profondeurs de Brassenoire]=],
	hint = [=[Cherchez la chose que le culte vénère dans le bassin le plus profond des Profondeurs de Brassenoire.]=],
	allegiance = [=[Les Dieux très anciens · vénérée par le Marteau du crépuscule]=],
	aliases = { "Aku'Mai", "Princesse des profondeurs" },
	sections = {
		{
			title = "Résumé",
			text = [=[Aku'mai est une hydre à trois têtes d'une taille immense, une servante des {red:old-gods}Dieux très anciens{/red}. Quand la corruption de ces puissances anciennes s'infiltra dans le puits de lune du temple englouti, elle surgit de ses eaux et fit des ruines son antre. Elle porte un éclat de la force de ses maîtres, et sa faim de chair vivante est sans fin. Le {link:twilight-s-hammer}Marteau du crépuscule{/link} la vénère comme le signe que les Dieux très anciens reviendront, et la nourrit de sacrifices.]=],
		},
		{
			title = "Importance",
			text = [=[Aku'mai est la raison pour laquelle le culte vint aux {link:blackfathom-deeps}Profondeurs de Brassenoire{/link}. Pour le {link:twilight-s-hammer}Marteau du crépuscule{/link}, elle est divine : la preuve que ses sombres maîtres s'agitent encore sous le monde, et une source de pouvoir pour quiconque la sert. Les nagas récoltent en son nom les saphirs des grottes, et ses cultistes rêvent du jour où elle ramènera sur {link:azeroth}Azeroth{/link} le règne des Dieux très anciens. Pour l'{link:argent-dawn}Aube d'argent{/link} et le {link:earthen-ring}Cercle terrestre{/link}, elle est une plaie purulente sur la côte d'{link:ashenvale}Orneval{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle surgit du puits de lune souillé de l'ancien temple d'Elune.
• Elle a dévoré les innocents que le culte lui sacrifie.
• Des bêtes qui portent son nom, les claque-mâchoires et les pêcheurs d'Aku'mai, nagent dans les bassins, et des élémentaires d'eau la servent.]=],
		},
	},
	chapters = {
		{
			title = "Princesse des profondeurs",
			hint = [=[Retrouvez le vieux manuscrit qui repose dans les profondeurs du temple.]=],
			text = [=[Dans les profondeurs reposait un écrit plus ancien que le culte, l'œuvre d'un elfe nommé Lorgalis. Il nommait Aku'mai la Princesse des profondeurs, une servante des Dieux très anciens qui demeurait dans le temple et bénissait ses grottes. Des mortels plus anciens l'avaient amenée là, disait-il. Elle ne détenait qu'un éclat de la puissance de ses maîtres, et pourtant celle-ci était sans mesure. Aussi était-elle vénérée, crainte et aimée.]=],
		},
		{
			title = "Les cristaux des profondeurs",
			hint = [=[Découvrez pourquoi les nagas récoltent des saphirs dans les grottes.]=],
			text = [=[On vit les nagas récolter les grands saphirs des grottes, et {link:je-neu-sancrea}Je'neu Sancrea{/link}, du {link:earthen-ring}Cercle terrestre{/link}, sentit les esprits de l'eau qui s'y attachaient. Une note froissée prise sur une prêtresse {link:naga}naga{/link} révéla le reste. Les cristaux étaient apportés à un chef du culte, pour aider ses aquamanciens dans leurs invocations. En maîtrisant leur pouvoir, le culte espérait apaiser Aku'mai, et un jour l'appeler tout entière pour rendre le monde au règne des Dieux très anciens.]=],
		},
	},
	mentions = {
		{ text = "Infamie à {link:blackfathom-deeps}Brassenoire{/link}" },
		{ text = "L'essence d'Aku'Mai" },
	},
	bonds = {
		{ id = "twilight-lord-kelris", name = "Seigneur du crépuscule Kelris", note = "son grand prêtre" },
		{ id = "lorgus-jett", name = "Lorgus Jett", note = "cherchait à l'apaiser" },
		{ id = "lady-sarevess", name = "Dame Sarevess", note = "sert le culte qui la vénère" },
	},
})

Translate("frFR", "twilight-lord-kelris", {
	title = "Seigneur du crépuscule Kelris",
	subtitle = "Seigneur du Marteau du crépuscule dans les Profondeurs",
	found = [=[Le sanctum du Sanctuaire lunaire, devant l'autel des Dieux très anciens]=],
	hint = [=[Cherchez le maître du culte dans le sanctum du temple englouti.]=],
	allegiance = "Marteau du crépuscule",
	aliases = { "Kelris" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le seigneur du crépuscule Kelris dirige le {link:twilight-s-hammer}Marteau du crépuscule{/link} dans les {link:blackfathom-deeps}Profondeurs de Brassenoire{/link}. Il est assis en transe dans le sanctum de l'ancien temple, près de l'autel où le culte fait ses offrandes. Sous son règne, les cultistes sacrifient des innocents à l'hydre {link:aku-mai}Aku'mai{/link}, et gagnent du pouvoir en retour. Kelris manie la magie de l'ombre et du sommeil, et au combat il peut plonger ses ennemis dans un sommeil impuissant.]=],
		},
		{
			title = "Importance",
			text = [=[Pendant longtemps, Kelris échappa à l'{link:argent-dawn}Aube d'argent{/link}. Ses guetteurs de {link:darnassus}Darnassus{/link} disent que chaque fois que le mal se montrait sur ces terres, Kelris y avait trempé, et pendant des années ils le crurent mort ou perdu. Il n'était ni l'un ni l'autre. Il était descendu dans les Profondeurs pour servir les {red:old-gods}Dieux très anciens{/red}, et il comptait ramener le monde au chaos de leur âge. Les taurens de {link:thunder-bluff}Thunder Bluff{/link} l'appellent une créature du mal pur.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il mena le {link:twilight-s-hammer}Marteau du crépuscule{/link} dans le temple englouti d'Elune.
• Il allia le culte aux nagas de {link:blackfathom-deeps}Brassenoire{/link}.
• Il offrit des innocents à {link:aku-mai}Aku'mai{/link} en échange de pouvoir.]=],
		},
	},
	chapters = {
		{
			title = "Le rapport de l'éclaireur",
			hint = [=[Retrouvez l'éclaireur perdu de l'Aube d'argent dans les Profondeurs.]=],
			text = [=[L'{link:argent-dawn}Aube d'argent{/link} envoya un éclaireur surveiller le temple, et des semaines passèrent sans nouvelles. Quand on le retrouva enfin, il gisait blessé dans les grottes, à bout de forces. Il avait appris ce que faisait le culte. Le {link:twilight-s-hammer}Marteau du crépuscule{/link} et les nagas tenaient ensemble les ruines, et leur chef, Kelris, livrait des innocents à l'hydre en échange de pouvoir. L'éclaireur ne pouvait rien faire de plus. Il demanda que Kelris soit tué et que sa tête soit rapportée hors des Profondeurs.]=],
		},
		{
			title = "La tête de Kelris",
			hint = "Mettez fin au règne du seigneur du crépuscule.",
			text = [=[Quand la tête de Kelris fut apportée à l'{link:argent-dawn}Aube d'argent{/link} à {link:darnassus}Darnassus{/link}, le guetteur de l'aube Selgorm dit que tout prenait enfin sens : l'homme qu'ils croyaient mort était depuis toujours derrière le mal. Pour la {link:horde}Horde{/link}, Bashana Runetotem rendit grâce à la Terre-mère, et dit que sacrifier autrui à un serviteur des Dieux très anciens pour son propre profit dépassait les mots. Par sa mort, de nombreuses vies innocentes furent épargnées.]=],
		},
	},
	mentions = {
		{ text = "La chute du Crépuscule" },
		{
			text = [=[Infamie à {link:blackfathom-deeps}Brassenoire{/link}, la tête portée à {link:darnassus}Darnassus{/link}]=],
		},
		{
			text = [=[Infamie à {link:blackfathom-deeps}Brassenoire{/link}, la tête portée à {link:thunder-bluff}Thunder Bluff{/link}]=],
		},
	},
	bonds = {
		{ id = "aku-mai", name = "Aku'mai", note = "la puissance qu'il sert" },
		{ id = "argent-guard-thaelrid", name = "Garde d'argent Thaelrid", note = "l'éclaireur qui le démasqua" },
		{ id = "lorgus-jett", name = "Lorgus Jett", note = "un serviteur du même culte" },
	},
})

Translate("frFR", "argent-guard-thaelrid", {
	title = "Garde d'argent Thaelrid",
	subtitle = "Éclaireur de l'Aube d'argent",
	found = [=[Les grottes près du bassin d'Ask'ar, dans les Profondeurs de Brassenoire]=],
	hint = [=[Cherchez l'éclaireur perdu de l'Aube d'argent dans les grottes inondées des Profondeurs de Brassenoire.]=],
	allegiance = "Aube d'argent · Elfes de la nuit",
	aliases = { "Thaelrid" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le garde d'argent Thaelrid est un {link:night-elves}elfe de la nuit{/link} de l'{link:argent-dawn}Aube d'argent{/link}. {red:dawnwatcher-shaedlass}La guetteuse de l'aube Shaedlass{/red} l'envoya de {link:darnassus}Darnassus{/link} surveiller le {link:twilight-s-hammer}Marteau du crépuscule{/link} et les nagas dans les {link:blackfathom-deeps}Profondeurs de Brassenoire{/link}. Il découvrit leur secret, mais il fut blessé et ne put revenir. Il attend dans les grottes, trop faible pour continuer, et demande à ceux qui le trouvent d'achever ce qu'il n'a pu faire : tuer le seigneur du crépuscule {link:twilight-lord-kelris}Kelris{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Un complot odieux",
			hint = [=[Répondez à l'appel de l'Aube d'argent et cherchez son éclaireur.]=],
			text = [=[Des semaines après être entré dans les Profondeurs, Thaelrid fut retrouvé vivant. Shaedlass avait eu raison de s'inquiéter, dit-il. Un complot odieux se tramait en ce lieu corrompu.]=],
		},
	},
	mentions = {
		{ text = "Infamie à {link:blackfathom-deeps}Brassenoire{/link}" },
	},
	bonds = {
		{ id = "twilight-lord-kelris", name = "Seigneur du crépuscule Kelris", note = "l'ennemi qu'il démasqua" },
	},
})

Translate("frFR", "morridune", {
	title = "Morridune",
	subtitle = "Le cultiste repenti",
	found = "L'antre d'Aku'mai, après la chute de l'hydre",
	hint = [=[Cherchez celui qui attendait d'être libéré de l'antre de l'hydre.]=],
	allegiance = "Jadis du Marteau du crépuscule · Darnassus",
	sections = {
		{
			title = "Résumé",
			text = [=[Morridune est un {link:dwarves}nain{/link} de Khaz Modan qui suivit jadis le {link:twilight-s-hammer}Marteau du crépuscule{/link}. Il vint dans les Profondeurs obsédé par les {red:old-gods}Dieux très anciens{/red}, espérant tirer du pouvoir d'{link:aku-mai}Aku'mai{/link}. Puis il vit le culte sacrifier d'innombrables innocents, et il reprit ses esprits. Pour cela, il fut pris au piège dans l'antre de l'hydre. Quand Aku'mai mourut, il s'écria qu'il pouvait enfin partir. En signe de gratitude, il ouvre un passage vers {link:darnassus}Darnassus{/link} aux tueurs de l'hydre qui sont amis de l'{link:alliance}Alliance{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Morridune est la preuve que certains de ceux qui tombent aux mains du Marteau peuvent revenir en arrière.]=],
		},
	},
	bonds = {
		{ id = "aku-mai", name = "Aku'mai", note = "la bête qu'il chercha jadis à servir" },
	},
})

Translate("frFR", "ghamoo-ra", {
	title = "Ghamoo-ra",
	subtitle = "La tortue tourmentée",
	found = "L'île du bassin d'Ask'ar",
	hint = [=[Affrontez la grande tortue qui arpente l'île de la grotte inondée.]=],
	allegiance = "Marteau du crépuscule",
	sections = {
		{
			title = "Résumé",
			text = [=[Ghamoo-ra est une tortue géante du temple englouti. On dit qu'il était l'une des dernières créatures paisibles à y vivre quand le {link:twilight-s-hammer}Marteau du crépuscule{/link} arriva. Les cultistes le réveillèrent et l'enchaînèrent. Pendant des années, ils le tourmentèrent dans son corps et dans son esprit, jusqu'à ce qu'il devienne fou. Ils lui donnèrent son nom et le dressèrent à attaquer tout étranger qui approchait de leur sanctuaire. Désormais, il piétine tous ceux qui mettent le pied sur son île, tandis que de plus petites tortues nagent autour de lui.]=],
		},
		{
			title = "Importance",
			text = [=[Ghamoo-ra est le premier gardien des Profondeurs, et la cruauté du culte faite chair.]=],
		},
	},
	bonds = {
		{ id = "twilight-lord-kelris", name = "Seigneur du crépuscule Kelris", note = "le maître de ses tourmenteurs" },
	},
})

Translate("frFR", "lady-sarevess", {
	title = "Dame Sarevess",
	subtitle = "Sorcière des mers des nagas",
	found = "Une anse latérale du bassin d'Ask'ar",
	hint = "Affrontez la sorcière naga qui tient une anse bien à elle.",
	allegiance = "Nagas · Marteau du crépuscule",
	aliases = { "Sarevess" },
	sections = {
		{
			title = "Résumé",
			text = [=[Dame Sarevess est une sorcière {link:naga}naga{/link}, une maîtresse dévoyée de la foudre et du givre. On dit que le {link:twilight-s-hammer}Marteau du crépuscule{/link} lui a accordé une anse bien à elle dans les Profondeurs et ne cesse de lui envoyer de nouveaux sacrifices. En retour, les cultistes espèrent que ses rites leur donneront une magie assez puissante pour vénérer l'hydre sans devenir son prochain repas. Elle accueille les intrus en criant à ses gardes de les tuer.]=],
		},
		{
			title = "Importance",
			text = [=[Sarevess lie les nagas aux desseins du culte. Son œuvre est le bouclier du Marteau contre son propre dieu.]=],
		},
	},
	bonds = {
		{ id = "aku-mai", name = "Aku'mai", note = "la bête contre laquelle ses rites protégeraient" },
		{ id = "twilight-lord-kelris", name = "Seigneur du crépuscule Kelris", note = "son allié dans le culte" },
	},
})

Translate("frFR", "gelihast", {
	title = "Gelihast",
	subtitle = "Chef des murlocs Blindlight",
	found = "Le sanctuaire de Gelihast",
	hint = [=[Affrontez le chef murloc qui tient son propre sanctuaire dans les Profondeurs.]=],
	allegiance = "Murlocs Blindlight",
	sections = {
		{
			title = "Résumé",
			text = [=[Gelihast est le chef des murlocs Blindlight, un combattant féroce armé de deux lames et de filets. On dit que l'appel des {red:old-gods}Dieux très anciens{/red} l'attira dans les Profondeurs, et qu'il se fraya un chemin en massacrant près d'une douzaine de cultistes du {link:twilight-s-hammer}Marteau du crépuscule{/link}. Impressionné par sa sauvagerie, le culte le laissa rester. Il éleva son propre sanctuaire parmi ses murlocs, et là il offre des sacrifices et reçoit les bénédictions de la sombre présence des ruines.]=],
		},
		{
			title = "Importance",
			text = [=[Gelihast montre que les Dieux très anciens appellent jusqu'aux plus humbles créatures de la mer.]=],
		},
	},
	bonds = {
		{ id = "aku-mai", name = "Aku'mai", note = "la présence qu'il vénère" },
	},
})

Translate("frFR", "lorgus-jett", {
	title = "Lorgus Jett",
	subtitle = "Serviteur du Marteau du crépuscule",
	found = [=[Les tunnels et les ruines des Profondeurs de Brassenoire, où il se déplace de façon imprévisible]=],
	hint = [=[Traquez le cultiste qui rassemble les saphirs des Profondeurs.]=],
	allegiance = "Marteau du crépuscule",
	aliases = { "Lorgus" },
	sections = {
		{
			title = "Résumé",
			text = [=[Lorgus Jett est un humain du {link:twilight-s-hammer}Marteau du crépuscule{/link} qui invoque la foudre au combat. Les prêtresses nagas des Profondeurs lui apportent les saphirs des grottes, où les esprits de l'eau sont puissants. Grâce à eux, il compte renforcer les aquamanciens du culte, apaiser {link:aku-mai}Aku'mai{/link}, et enfin la ramener tout entière pour régner sur le monde au nom des {red:old-gods}Dieux très anciens{/red}.]=],
		},
	},
	chapters = {
		{
			title = "Un nom pour nos tourments",
			hint = [=[Portez la note humide d'une prêtresse naga au Cercle terrestre.]=],
